-- HA Marketing real shop backend. Run once; safe to re-run.
create table if not exists public.shop_categories(category_key text primary key,name text not null,sort_order int not null default 0,is_active boolean not null default true);
insert into public.shop_categories(category_key,name,sort_order) values
('library','مكتبة',1),('building_materials','مواد البناء',2),('cards_credit','بطاقات وأرصدة',3),('yugioh','أوراق يوغي',4),('markets','أسواق',5),('restaurants','مطاعم',6),('flowers','ورد',7),('home_appliances','أجهزة منزلية',8),('printers','طابعات',9),('devices','أجهزة',10),('device_accessories','إكسسوارات الأجهزة',11),('clothes','ملابس',12),('shoes','أحذية',13) on conflict(category_key) do update set name=excluded.name,sort_order=excluded.sort_order;
create table if not exists public.shop_products(id bigint generated by default as identity primary key,category_key text not null references public.shop_categories(category_key),name text not null,description text,price_iqd bigint not null check(price_iqd>=0),stock_qty int not null default 0 check(stock_qty>=0),image_url text,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.shop_orders(id bigint generated by default as identity primary key,customer_id uuid not null references auth.users(id) on delete restrict,status text not null default 'new' check(status in('new','confirmed','preparing','shipped','completed','cancelled')),phone text not null,address text not null,notes text,payment_method text not null default 'cash_on_delivery',total_iqd bigint not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.shop_order_items(id bigint generated by default as identity primary key,order_id bigint not null references public.shop_orders(id) on delete cascade,product_id bigint references public.shop_products(id) on delete set null,product_name text not null,qty int not null check(qty>0),unit_price_iqd bigint not null check(unit_price_iqd>=0));
alter table public.shop_categories enable row level security;alter table public.shop_products enable row level security;alter table public.shop_orders enable row level security;alter table public.shop_order_items enable row level security;
drop policy if exists "public read shop categories" on public.shop_categories;create policy "public read shop categories" on public.shop_categories for select using(is_active=true or public.is_admin());
drop policy if exists "public read active products" on public.shop_products;create policy "public read active products" on public.shop_products for select using(is_active=true or public.is_admin());
drop policy if exists "admin manage products" on public.shop_products;create policy "admin manage products" on public.shop_products for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists "customer read own shop orders" on public.shop_orders;create policy "customer read own shop orders" on public.shop_orders for select to authenticated using(customer_id=auth.uid() or public.is_admin());
drop policy if exists "admin read shop items" on public.shop_order_items;create policy "admin read shop items" on public.shop_order_items for select to authenticated using(public.is_admin() or exists(select 1 from public.shop_orders o where o.id=order_id and o.customer_id=auth.uid()));
create or replace function public.create_shop_order(p_items jsonb,p_phone text,p_address text,p_notes text default null) returns bigint language plpgsql security definer set search_path=public as $$declare v_order bigint;v_item jsonb;v_product public.shop_products%rowtype;v_qty int;v_total bigint:=0;begin if auth.uid() is null then raise exception 'Login required';end if;if coalesce(trim(p_phone),'')='' or coalesce(trim(p_address),'')='' then raise exception 'Phone and address required';end if;if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'Cart is empty';end if;insert into public.shop_orders(customer_id,phone,address,notes) values(auth.uid(),trim(p_phone),trim(p_address),nullif(trim(p_notes),'')) returning id into v_order;for v_item in select * from jsonb_array_elements(p_items) loop v_qty:=greatest(1,coalesce((v_item->>'qty')::int,1));select * into v_product from public.shop_products where id=(v_item->>'product_id')::bigint and is_active=true for update;if not found then raise exception 'Product unavailable';end if;if v_product.stock_qty<v_qty then raise exception 'Insufficient stock for %',v_product.name;end if;update public.shop_products set stock_qty=stock_qty-v_qty,updated_at=now() where id=v_product.id;insert into public.shop_order_items(order_id,product_id,product_name,qty,unit_price_iqd) values(v_order,v_product.id,v_product.name,v_qty,v_product.price_iqd);v_total:=v_total+(v_product.price_iqd*v_qty);end loop;update public.shop_orders set total_iqd=v_total where id=v_order;insert into public.notifications(user_id,title,message,order_id,kind) values(auth.uid(),'تم استلام طلب الشراء','تم إنشاء طلب الشراء رقم #'||v_order||' وسيتم تحديث حالته داخل حسابك.',null,'shop_order');return v_order;exception when others then raise;end$$;
grant execute on function public.create_shop_order(jsonb,text,text,text) to authenticated;
create or replace function public.cancel_shop_order(p_order_id bigint) returns void language plpgsql security definer set search_path=public as $$declare r record;begin if not exists(select 1 from public.shop_orders where id=p_order_id and customer_id=auth.uid() and status='new') then raise exception 'Order cannot be cancelled';end if;for r in select product_id,qty from public.shop_order_items where order_id=p_order_id and product_id is not null loop update public.shop_products set stock_qty=stock_qty+r.qty,updated_at=now() where id=r.product_id;end loop;update public.shop_orders set status='cancelled',updated_at=now() where id=p_order_id;end$$;grant execute on function public.cancel_shop_order(bigint) to authenticated;
create or replace function public.admin_update_shop_order_status(p_order_id bigint,p_status text) returns void language plpgsql security definer set search_path=public as $$declare uid uuid;begin if not public.is_admin() then raise exception 'Not allowed';end if;if p_status not in('confirmed','preparing','shipped','completed','cancelled') then raise exception 'Invalid status';end if;select customer_id into uid from public.shop_orders where id=p_order_id;if uid is null then raise exception 'Order not found';end if;update public.shop_orders set status=p_status,updated_at=now() where id=p_order_id;insert into public.notifications(user_id,title,message,kind) values(uid,'تحديث طلب الشراء','تم تحديث حالة طلب الشراء #'||p_order_id||' إلى '||case p_status when 'confirmed' then 'مؤكد' when 'preparing' then 'قيد التجهيز' when 'shipped' then 'تم الشحن' when 'completed' then 'مكتمل' when 'cancelled' then 'ملغي' end,'shop_order_status');end$$;grant execute on function public.admin_update_shop_order_status(bigint,text) to authenticated;
